/* From Uiverse.io by Nawsome - Tags: loader */
.__UIV_SCOPE__ .loading {
  width: 100px;
  height: 100px;
  background: white;
  border-radius: 12px;
  position: relative;
  transform-style: preserve-3d;
  animation: loading_4123 2s linear infinite;
}

.__UIV_SCOPE__ .side {
  background: white;
  border-radius: 12px;
}

.__UIV_SCOPE__ .front, .__UIV_SCOPE__ .back {
  width: 100px;
  height: 100px;
}

.__UIV_SCOPE__ .front, .__UIV_SCOPE__ .back {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;
}

.__UIV_SCOPE__ .back {
  transform: translateZ(-10px);
}

.__UIV_SCOPE__ .left, .__UIV_SCOPE__ .right {
  width: 10px;
  height: calc(100% - 12px);
  top: 6px;
  position: absolute;
  background: #efefef;
}

.__UIV_SCOPE__ .left {
  left: 0;
  transform-origin: 0;
  transform: rotateY(90deg);
}

.__UIV_SCOPE__ .right {
  right: 0;
  transform-origin: 100%;
  transform: rotateY(-90deg);
}

.__UIV_SCOPE__ .top, .__UIV_SCOPE__ .bottom {
  width: calc(100% - 12px);
  height: 10px;
  position: absolute;
  left: 6px;
  background: #efefef;
}

.__UIV_SCOPE__ .top {
  top: -10px;
  transform-origin: 0 100%;
  transform: rotateX(90deg);
}

.__UIV_SCOPE__ .bottom {
  bottom: -10px;
  transform-origin: 0 0;
  transform: rotateX(-90deg);
}

@keyframes loading_4123 {
  0% {
    transform: rotate(0);
  }

  50% {
    transform: rotateY(180deg);
  }

  100% {
    transform: rotateY(180deg) rotateX(-180deg);
  }
}
